)

const (
	agentUnknown      = "unknown"
	dateUnknown       = "unknown"
	activityTimeframe = "last-month"
	activityLimit     = 1000
)

// knownAgents maps normalized agent strings from the API to display IDs.
// Used for the commit list, where per-checkpoint agent strings are free-form.
// The /me/activity endpoint returns already-normalized canonical IDs.
var knownAgents = map[string]string{
	"claude":     "claude",
	"claudecode": "claude",
	"gemini":     "gemini",
	"geminicli":  "gemini",
	"amp":        "amp",
	"codex":      "codex",
	"opencode":   "opencode",
	"copilot":    "copilot",
	"copilotcli": "copilot",
	"pi":         "pi",
	"cursor":     "cursor",
	"droid":      "droid",
	"kiro":       "kiro",
}

func newActivityCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "activity",
		Short: "Show your activity overview",
		Long:  "Display your activity overview, repository breakdown, and recent commits from entire.io",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runActivity(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr())
		},
	}
	return cmd
}

func runActivity(ctx context.Context, w, errW io.Writer) error {
	return runAuthenticatedActivityAPI(ctx, errW, false, func(ctx context.Context, client *api.Client) error {
		// Non-interactive fallback: piped output or accessibility mode
		if !interactive.IsTerminalWriter(w) || IsAccessibleMode() {
			return runActivityStatic(ctx, w, client)
		}

		return runActivityTUI(ctx, client)
	})
}

func runActivityStatic(ctx context.Context, w io.Writer, client *api.Client) error {
	activity, commits, err := fetchActivityData(ctx, client)
	if err != nil {
		return err
	}

	stats := contributionStats{
		Tasks:         activity.Stats.Tasks,
		Throughput:    activity.Stats.Throughput,
		Iteration:     activity.Stats.Iteration,
		ContinuityH:   activity.Stats.ContinuityHours,
		Streak:        activity.Stats.LifetimeStreak,
		CurrentStreak: activity.Stats.LifetimeCurrentStreak,
	}
	days := groupCommitsByDay(commits)

	sty := newActivityStyles(w)
	renderActivity(w, sty, stats, activity.Repos, activity.HourlyContributions, days)
	return nil
}

// fetchActivityData fetches aggregated activity and commits concurrently.
func fetchActivityData(ctx context.Context, client *api.Client) (*userActivityResponse, []userCommit, error) {
	var activity *userActivityResponse
	var commits []userCommit

	g, gCtx := errgroup.WithContext(ctx)
	g.Go(func() error {
		var err error
		activity, err = fetchActivity(gCtx, client)
		return err
	})

type userCommitsResponse struct {
	Commits   []userCommit `json:"commits"`
	Timeframe string       `json:"timeframe"`
	UpdatedAt string       `json:"updated_at"`
}

// Computed types used for rendering.

type contributionStats struct {
	Tasks         int
	Throughput    float64 // avg tokens/checkpoint in thousands
	Iteration     float64 // avg session_count per checkpoint
	ContinuityH   float64 // peak session length in hours (max(steps)*2/60)
	Streak        int     // longest consecutive days (last 365)
	CurrentStreak int     // current streak ending today (last 365)
}

// repoContribution matches the API's `repos[]` shape. Agents is keyed by the
// canonical agent ID (claude, gemini, …, unknown) with all 11 keys populated.
type repoContribution struct {
	Repo   string              `json:"repo"`
	Total  int                 `json:"total"`
	Agents activityAgentCounts `json:"agents"`
}

// hourlyPoint matches the API's `hourly_contributions[]` shape. AgentID is a
// canonical ID (no client-side normalization needed).
type hourlyPoint struct {
	Date    string `json:"date"` // "2006-01-02", in the caller's timezone
	Hour    int    `json:"hour"`
	AgentID string `json:"agent"`
	Value   int    `json:"value"`
}

// commitDay groups commits by date for display.
type commitDay struct {
	Date    string
	Commits []userCommit
}

package httpapi

import (
	"context"
	"net/http"
	"time"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entire-api/internal/store"
)

// meUserSession is one row of GET /me/sessions — entire.io's UserSessionListItem:
// the repo-scoped SessionListItem (camelCase) plus the two cross-repo fields it
// adds (repo_full_name, is_private — snake_case). The mixed casing mirrors
// entire.io exactly so the web BFF needs no per-field mapping.
//
// repo_full_name carries the repo's full name when resolved, else the repo_id
// ULID. is_private is the origin's observed visibility (schema_version>=2), false
// when unobserved — resolved via repoDisplay, matching /me/checkpoints.
type meUserSession struct {
	SessionListItem
	RepoFullName string `json:"repo_full_name"`
	IsPrivate    bool   `json:"is_private"`
}

// MeSessionsOutput is GET /me/sessions — the bare entire.io envelope
// { sessions, timeframe, updated_at } (handleUserSessions). updated_at is a
// JS-toISOString-formatted string (not the experimental endpoints' time.Time).
type MeSessionsOutput struct {
	Body struct {
		Sessions  []meUserSession `json:"sessions"`
		Timeframe string          `json:"timeframe"`
		UpdatedAt string          `json:"updated_at"`
	}
}

// repoSession pairs a materialised session with its source repo's resolved
// display, carried until the global ordering + limit are applied across repos.
type repoSession struct {
	session      store.Session
	repoID       string // the portable origin id (repo_group ULID for a mirror, else repo id)
	repoFullName string
	isPrivate    bool
}

// meSessionsSpineCap bounds the checkpoint-spine scan that discovers the
// caller's sessions. It is independent of the user-facing result limit: a very
// large timeframe could otherwise scan the whole checkpoint history.
const meSessionsSpineCap = 1000

// registerMeSessions wires GET /me/sessions: the cross-repo session list for the
// dashboard. The per-user spine is my_activity (access-filtered, fail-closed) —
// it identifies which checkpoints, and so which sessions, are the caller's.
// my_activity carries no session ids, so the caller's checkpoints are mapped to
// their sessions through the local repo store, which also hydrates the
// materialised session rows (the same source the per-repo sessions page reads).
//
// Sessions are attributed to the caller by my_activity membership rather than by
// commit-author login (entire.io's first_commit_author_username); entire-api has
// no GitHub-login-on-session source today, so firstCommitAuthorUsername is null and
// isPublic is false — consistent with the repo sessions surface. is_private is
// resolved from the origin's observed visibility (repoDisplay), matching /me/checkpoints.
//
// The spine's repo ids are resolved origin-aware (localPlacementID) before the
// session reads, so a mirrored repo's sessions come from this cell's own placement
// rather than the last-reporter (possibly foreign) repo_id — the same origin keying
// /me and /experimental/me use.
func registerMeSessions(api huma.API, repoDeps *RepoActivityDeps, userDeps *UserActivityDeps) {
	mw := []func(huma.Context, func(huma.Context)){requireAuth(api, userDeps.Authenticator)}
	huma.Register(api, huma.Operation{
		OperationID: "listMySessions", Method: http.MethodGet, Path: apiPrefix + "/me/sessions",
		Summary: "My sessions in a timeframe, across repos",
		Tags:    []string{"me"}, Security: secSchemes, Errors: stdErrors, Middlewares: mw,
	},
		func(ctx context.Context, in *TimeframeInput) (*MeSessionsOutput, error) {
			tf := parseTimeframe(in)
			acc := id(ctx)

			// Spine: the caller's own checkpoints in-window tell us which repos +
			// sessions are theirs.
			rows, err := loadAccessible(ctx, userDeps, store.ActivityQuery{
				AccountID: acc, Type: "checkpoint", Since: tf.since, Until: tf.until,
				States: countedStates, Limit: meSessionsSpineCap,
			})
			if err != nil {
				return nil, err
			}

			// Metadata resolved both ways (byRepoID + byGroup), like /me/checkpoints:
			// lets a deduped mirror row resolve display + its LOCAL placement from the
			// origin rather than its last-reporter repo_id.
			metas, err := repoMetaMap(ctx, repoDeps, rows)
			if err != nil {
				return nil, err
			}

			// Group the spine's checkpoints by their portable ORIGIN (the repo_group
			// ULID for a mirror, else the repo id) so a mirror's placements fold to one
			// logical repo. Per origin we carry its checkpoint ids, this cell's LOCAL
			// placement (the repo to read content FROM), and the resolved display.
			type originGroup struct {
				localPlacement string
				fullName       string
				isPrivate      bool
				checkpointIDs  []string
			}
			groups := map[string]*originGroup{}
			originOrder := make([]string, 0)
			for _, r := range rows {
				origin := store.OriginOf(r.OriginKey, r.RepoID)
				g, ok := groups[origin]
				if !ok {
					name, priv := repoDisplay(metas, r.OriginKey, r.RepoID)
					g = &originGroup{
						localPlacement: localPlacementID(metas, r.OriginKey, r.RepoID),
						fullName:       name,
						isPrivate:      priv,
					}
					groups[origin] = g
					originOrder = append(originOrder, origin)
				}
				g.checkpointIDs = append(g.checkpointIDs, r.CheckpointID)
			}

			// Two resolutions stack before the session-table reads. (1) origin→local
			// placement: a deduped mirror row's repo_id is the last-reporter, possibly
			// a placement foreign to this cell that holds none of the content, so read
			// from this cell's own placement of the origin (localPlacementID, already
			// applied when the group was built). (2) code→storage: the
			// checkpoints/sessions tables are keyed under the checkpoint storage repo
			// (the placement itself when self-hosted, a separate repo for a configured
			// checkpoint_remote). Skipping either reads an empty repo and the sessions
			// are silently dropped. Both resolutions and the session-page reads are
			// batched across every origin so the spine's origins cost a fixed set of
			// queries rather than three per origin.
			placements := make([]string, 0, len(originOrder))
			for _, origin := range originOrder {
				placements = append(placements, groups[origin].localPlacement)
			}
			storageByPlacement, err := repoDeps.Store.CheckpointStorageRepoIDs(ctx, placements)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: checkpoint storage repos", err)
			}
			queries := make([]store.OriginSessionQuery, 0, len(originOrder))
			for _, origin := range originOrder {
				g := groups[origin]
				queries = append(queries, store.OriginSessionQuery{
					OriginKey:     origin,
					StorageRepoID: storageByPlacement[g.localPlacement],
					CheckpointIDs: g.checkpointIDs,
				})
			}
			// Window + order match entire.io's listSessionsForUser (last_activity in
			// [since,until], newest first); each origin's checkpoint set scopes the read
			// to the caller's sessions.
			originSessions, err := repoDeps.Store.SessionsForOriginCheckpoints(ctx, queries, tf.since, tf.until, tf.limit)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: sessions", err)
			}
			// Already in the canonical global order (last_activity descending, then
			// session_id ascending) and capped to the limit — the store's ORDER BY +
			// LIMIT own the cross-repo merge, so no re-sort is needed here.
			collected := make([]repoSession, 0, len(originSessions))
			for _, os := range originSessions {
				g := groups[os.OriginKey]
				collected = append(collected, repoSession{session: os.Session, repoID: os.OriginKey, repoFullName: g.fullName, isPrivate: g.isPrivate})
			}

			meAccountIDs := make([]string, 0, len(collected))
			for _, rs := range collected {
				meAccountIDs = append(meAccountIDs, rs.session.FirstCommitAuthorAccount)
			}
			meResolved := resolveAuthorUsernames(ctx, repoDeps.AuthorUsernames, meAccountIDs)
			out := &MeSessionsOutput{}
			out.Body.Sessions = make([]meUserSession, 0, len(collected))
			for _, rs := range collected {
				out.Body.Sessions = append(out.Body.Sessions, meUserSession{
					SessionListItem: sessionToItem(rs.session, meResolved),
					RepoFullName:    rs.repoFullName,
					IsPrivate:       rs.isPrivate,
				})
			}
			out.Body.Timeframe = tf.name
			out.Body.UpdatedAt = isoTime(time.Now().UTC())
			return out, nil
		})
}

