// --- session list -----------------------------------------------------

// SessionListItem mirrors entire.io's SessionListItem (flat attribution*).
type SessionListItem struct {
	SessionID                 string  `json:"sessionId"`
	DisplayName               string  `json:"displayName"`
	CustomName                *string `json:"customName"`
	IsPublic                  bool    `json:"isPublic"`
	Agent                     *string `json:"agent"`
	Model                     *string `json:"model"`
	Prompt                    *string `json:"prompt"`
	FirstCommitAuthorUsername *string `json:"firstCommitAuthorUsername"`
	StartedAt                 string  `json:"startedAt"`
	LastActivityAt            string  `json:"lastActivityAt"`
	CheckpointCount           int     `json:"checkpointCount"`
	StepCount                 int     `json:"stepCount"`
	InputTokens               *int64  `json:"inputTokens"`
	OutputTokens              *int64  `json:"outputTokens"`
	CacheCreationTokens       *int64  `json:"cacheCreationTokens"`
	CacheReadTokens           *int64  `json:"cacheReadTokens"`
	AttributionAgentLines     *int64  `json:"attributionAgentLines"`
	AttributionHumanAdded     *int64  `json:"attributionHumanAdded"`
	AttributionHumanModified  *int64  `json:"attributionHumanModified"`
	AttributionHumanRemoved   *int64  `json:"attributionHumanRemoved"`
	AttributionTotalCommitted *int64  `json:"attributionTotalCommitted"`
	AttributionCalculatedAt   *string `json:"attributionCalculatedAt"`
}

// sessionToItem maps a stored session to the wire item. resolved is the
// pre-fetched map of accountID → GitHub login from entire-core (may be empty
// when the resolver is not configured or the account is unknown); the helper
// falls back to the stored GitHub login, then nil.
func sessionToItem(s store.Session, resolved map[string]string) SessionListItem {
	return SessionListItem{
		SessionID: s.SessionID, DisplayName: s.DisplayName, CustomName: strPtr(s.CustomName),
		IsPublic: false, Agent: strPtr(s.Agent), Model: strPtr(s.Model), Prompt: strPtr(s.Prompt),
		FirstCommitAuthorUsername: authorUsername(s.FirstCommitAuthorAccount, s.FirstCommitAuthorGitHubLogin, resolved),
		StartedAt:                 isoTime(s.StartedAt), LastActivityAt: isoTime(s.LastActivityAt),
		CheckpointCount: s.CheckpointCount, StepCount: s.StepCount,
		InputTokens: s.InputTokens, OutputTokens: s.OutputTokens,
		CacheCreationTokens: s.CacheCreation, CacheReadTokens: s.CacheRead,
		AttributionAgentLines: s.AttrAgentLines, AttributionHumanAdded: s.AttrHumanAdded,
		AttributionHumanModified: s.AttrHumanModified, AttributionHumanRemoved: s.AttrHumanRemoved,
		AttributionTotalCommitted: s.AttrTotalCommitted, AttributionCalculatedAt: isoPtr(s.AttrCalculatedAt),
	}
}

// SessionsListInput is GET .../sessions (entire.io: branch + cursor + limit).
// Limit is clamped (not rejected) in the handler to match entire.io. Branch is
// optional — empty resolves to the repo's default branch (ResolveBranchName).
type SessionsListInput struct {
	RepoID string `path:"repo_id"`
	Branch string `query:"branch" doc:"Branch to filter to; empty = the repo's default branch"`
	Cursor string `query:"cursor"`
	Limit  int    `query:"limit" default:"50" doc:"Page size, clamped to 1..200"`
}

// sessionsMaxLimit / checkpointsMaxLimit mirror entire.io's caps (it clamps
// out-of-range limits rather than rejecting them).
const (
	sessionsDefaultLimit = 50
	sessionsMaxLimit     = 200
	checkpointsDefault   = 100
	checkpointsMaxLimit  = 1000
)

// clampLimit returns def for v < 1, max for v > max, else v (entire.io clamps).
func clampLimit(v, def, max int) int {
	if v < 1 {
		return def
	}
	if v > max {
		return max
	}
	return v
}

// RepoSessionsOutput is the entire.io sessions-list envelope.
type RepoSessionsOutput struct {
	Body struct {
		Sessions            []SessionListItem `json:"sessions"`
		NextCursor          *string           `json:"next_cursor"`
		RepoFullName        string            `json:"repo_full_name"`
		AppHasAccess        bool              `json:"app_has_access"`
		SessionBranchExists bool              `json:"session_branch_exists"`
		HistoryStatus       string            `json:"history_status"`
		HistoryComplete     bool              `json:"history_complete"`
		Source              string            `json:"source"`
	}
}

// SessionDetailInput / SessionDetailOutput — detail reuses the list item shape.
type SessionDetailInput struct {
	RepoID    string `path:"repo_id"`
	SessionID string `path:"session_id"`
}
type SessionDetailOutput struct{ Body SessionListItem }

// --- session rename ---------------------------------------------------

// SessionRenameInput is PATCH .../session/{id}/display-name (entire.io
// cache.ts:3858): { displayName: string|null } — null clears the override.
type SessionRenameInput struct {
	RepoID    string `path:"repo_id"`
	SessionID string `path:"session_id"`
	Body      struct {
		DisplayName *string `json:"displayName" maxLength:"200" doc:"New custom name; null clears the override"`
	}
}

// SessionRenameOutput is entire.io's { displayName } (the resolved name).
type SessionRenameOutput struct {
	Body struct {
		DisplayName string `json:"displayName"`
	}
}

