527	func uniqueCommitAgents(c userCommit) []string {
528		seen := make(map[string]struct{})
529		var result []string
530		for _, cp := range c.Checkpoints {
531			agents := cp.Agents
532			// Fall back to singular Agent field when Agents slice is empty
533			if len(agents) == 0 && cp.Agent != "" {
534				agents = []string{cp.Agent}
535			}
536			for _, a := range agents {
537				id := normalizeAgentString(a)
538				if _, ok := seen[id]; !ok {
539					seen[id] = struct{}{}
540					result = append(result, id)
541				}
542			}
543		}
544		sort.Strings(result)
545		return result
546	}
547	
548	func formatCommitDate(dateStr string) string {
549		t, err := time.ParseInLocation("2006-01-02", dateStr, time.Local)
550		if err != nil {
551			return dateStr
552		}
553		now := time.Now().Local()
554		today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
555		days := int(today.Sub(t).Hours() / 24)
556	
557		switch days {
558		case 0:
559			return t.Format("Monday 2 Jan") + " (today)"
560		case 1:
561			return t.Format("Monday 2 Jan") + " (yesterday)"
562		default:
563			return t.Format("Monday 2 Jan")
564		}
565	}
566	
567	func padOrTruncate(s string, width int) string {
568		runes := []rune(s)
569		if len(runes) > width {
570			return string(runes[:width-1]) + "…"
571		}
572		return s + strings.Repeat(" ", width-len(runes))
573	}
574	
575	func truncateDisplayWidth(s string, width int, tail string) string {
576		if lipgloss.Width(s) <= width {
577			return s
578		}
579		if width <= 0 {
580			return ""
581		}
582		if lipgloss.Width(tail) >= width {
583			return tail[:width]
584		}
585	
586		var b strings.Builder
587		remaining := width - lipgloss.Width(tail)
588		for _, r := range s {
589			if lipgloss.Width(b.String()+string(r)) > remaining {
590				break
591			}
592			b.WriteRune(r)
593		}
594		return b.String() + tail
595	}
