/**
 * Format a raw model identifier into a short display label.
 *
 * Examples:
 *   "claude-opus-4-6"        -> "Opus 4.6"
 *   "claude-sonnet-4-6"      -> "Sonnet 4.6"
 *   "claude-haiku-4-5"       -> "Haiku 4.5"
 *   "claude-sonnet-4-20250514" -> "Sonnet 4"
 *   "gpt-4o"                 -> "GPT-4o"
 *   "gemini-2.0-flash"       -> "Gemini 2.0 Flash"
 *
 * Unknown formats pass through unchanged.
 */
export function formatModel(model: string | null | undefined): string | null {
  if (!model) return null
  const trimmed = model.trim()
  if (!trimmed) return null

  // Claude models: claude-<family>-<major>[-<minor>][-<YYYYMMDD>]
  // Date suffixes are 6+ digits; minor versions are short numerics.
  const claudeMatch = trimmed.match(/^claude-(opus|sonnet|haiku)-(\d+)(.*)$/i)
  if (claudeMatch) {
    const [, family, major, rest] = claudeMatch
    const familyLabel = family.charAt(0).toUpperCase() + family.slice(1).toLowerCase()
    const tailParts = rest.split("-").filter(Boolean)
    // A 6+ digit chunk is a date suffix — ignore everything from it onward.
    const minorParts: string[] = []
    for (const part of tailParts) {
      if (/^\d{6,}$/.test(part)) break
      minorParts.push(part)
    }
    const minor = minorParts.join(".")
    return minor ? `${familyLabel} ${major}.${minor}` : `${familyLabel} ${major}`
  }

  // GPT models: gpt-4o, gpt-4-turbo, gpt-3.5-turbo
  if (/^gpt-/i.test(trimmed)) {
    return "GPT-" + trimmed.replace(/^gpt-/i, "")
  }

  // Gemini: gemini-2.0-flash -> "Gemini 2.0 Flash"
  if (/^gemini-/i.test(trimmed)) {
    return trimmed
      .split("-")
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join(" ")
  }

  return trimmed
}

import { describe, it, expect } from "vitest"

import { formatModel } from "./model"

describe("formatModel", () => {
  it("formats current Claude identifiers", () => {
    expect(formatModel("claude-opus-4-6")).toBe("Opus 4.6")
    expect(formatModel("claude-sonnet-4-6")).toBe("Sonnet 4.6")
    expect(formatModel("claude-haiku-4-5")).toBe("Haiku 4.5")
  })

  it("strips legacy date suffixes from Claude identifiers", () => {
    expect(formatModel("claude-sonnet-4-20250514")).toBe("Sonnet 4")
    expect(formatModel("claude-opus-4-1-20250805")).toBe("Opus 4.1")
  })

  it("handles GPT models", () => {
    expect(formatModel("gpt-4o")).toBe("GPT-4o")
    expect(formatModel("gpt-4-turbo")).toBe("GPT-4-turbo")
  })

  it("returns null for empty input", () => {
    expect(formatModel(null)).toBeNull()
    expect(formatModel(undefined)).toBeNull()
    expect(formatModel("")).toBeNull()
    expect(formatModel("   ")).toBeNull()
  })

  it("passes through unknown formats", () => {
    expect(formatModel("custom-model-123")).toBe("custom-model-123")
  })
})

