309	func containsStr(s, sub string) bool {
310		return len(s) >= len(sub) && (s == sub || len(sub) == 0 ||
311			(len(s) > 0 && stringContains(s, sub)))
312	}
313	
314	func stringContains(s, sub string) bool {
315		for i := 0; i <= len(s)-len(sub); i++ {
316			if s[i:i+len(sub)] == sub {
317				return true
318			}
319		}
320		return false
321	}
