package cli

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"strings"

	"charm.land/bubbles/v2/key"
	"charm.land/bubbles/v2/spinner"
	"charm.land/bubbles/v2/viewport"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"
	"github.com/entireio/cli/cmd/entire/cli/api"
)

// activityDataMsg is sent when API data has been fetched. Exactly one of days
// (commits view) or sessionDays (sessions view) is populated, per showCommits.
type activityDataMsg struct {
	stats       contributionStats
	repos       []repoContribution
	hourly      []hourlyPoint
	days        []commitDay
	sessionDays []sessionDay
}

// activityErrMsg is sent when fetching fails.
type activityErrMsg struct{ err error }

type activityModel struct {
	// Data (nil until loaded)
	stats       *contributionStats
	repos       []repoContribution
	hourly      []hourlyPoint
	days        []commitDay
	sessionDays []sessionDay

	// showCommits selects the recent-list view: commits when true, else sessions.
	showCommits bool

	// Loading state
	loading bool
	loadErr error
	spinner spinner.Model

	// Fetch context
	ctx    context.Context
	client *api.Client

	// View state
	viewport viewport.Model
	sty      activityStyles
	useColor bool
	width    int
	height   int
	ready    bool
}

func runActivityTUI(ctx context.Context, client *api.Client, showCommits bool) error {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = lipgloss.NewStyle().Foreground(lipgloss.Color("8"))

	m := activityModel{
		loading:     true,
		spinner:     sp,
		ctx:         ctx,
		client:      client,
		useColor:    shouldUseColor(os.Stdout),
		showCommits: showCommits,
	}
	p := tea.NewProgram(m)
	if _, err := p.Run(); err != nil {
		return fmt.Errorf("activity TUI: %w", err)
	}
	return nil
}

func (m activityModel) fetchData() tea.Msg {
	if m.showCommits {
		activity, commits, err := fetchActivityWith(m.ctx, m.client, fetchCommits)
		if err != nil {
			return activityErrMsg{err: err}
		}
		return activityDataMsg{
			stats:  statsFromActivity(activity),
			repos:  activity.Repos,
			hourly: activity.HourlyContributions,
			days:   groupCommitsByDay(commits),
		}
	}

	activity, sessions, err := fetchActivityWith(m.ctx, m.client, fetchSessions)
	if err != nil {
		return activityErrMsg{err: err}
	}
	return activityDataMsg{
		stats:       statsFromActivity(activity),
		repos:       activity.Repos,
		hourly:      activity.HourlyContributions,
		sessionDays: groupSessionsByDay(sessions),
	}
}

func (m activityModel) Init() tea.Cmd {
	return tea.Batch(m.spinner.Tick, m.fetchData)
}

func (m activityModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case activityDataMsg:
		m.loading = false
		m.stats = &msg.stats
		m.repos = msg.repos
		m.hourly = msg.hourly
		m.days = msg.days
		m.sessionDays = msg.sessionDays
		if m.width > 0 {
			m = m.withViewport()
		}
		return m, nil

	case activityErrMsg:
		m.loading = false
		m.loadErr = msg.err
		return m, nil

	case tea.KeyPressMsg:
		if key.Matches(msg, keys.Quit) || key.Matches(msg, keys.Back) {
			return m, tea.Quit
		}
		if key.Matches(msg, keys.Home) {
			if m.ready {
				m.viewport.GotoTop()
			}
			return m, nil
		}
		if key.Matches(msg, keys.End) {
			if m.ready {
				m.viewport.GotoBottom()
			}
			return m, nil
		}

	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.sty = newActivityStylesWithWidth(m.width, m.useColor)
		if m.stats != nil {
			m = m.withViewport()
		}
		return m, nil

	case spinner.TickMsg:
		if m.loading {
			var cmd tea.Cmd
			m.spinner, cmd = m.spinner.Update(msg)
			return m, cmd
		}
	}

	if m.ready {
		var cmd tea.Cmd
		m.viewport, cmd = m.viewport.Update(msg)
		return m, cmd
	}

	return m, nil
}

func (m activityModel) withViewport() activityModel {
	headerHeight := m.headerLineCount()
	vpHeight := m.height - headerHeight - 1
	if vpHeight < 1 {
		vpHeight = 1
	}

	if !m.ready {
		m.viewport = viewport.New(viewport.WithWidth(m.width), viewport.WithHeight(vpHeight))
		m.ready = true
	} else {
		m.viewport.SetWidth(m.width)
		m.viewport.SetHeight(vpHeight)
	}
	m.viewport.SetContent(m.renderList())
	return m
}

func (m activityModel) View() tea.View {
	v := tea.View{AltScreen: true}
	if m.loadErr != nil {
		v.SetContent(fmt.Sprintf("\n  Failed to load activity: %s\n\n  Press q to quit.\n", m.loadErr))
		return v
	}

	if m.loading {
		v.SetContent(fmt.Sprintf("\n  %s Loading activity...\n", m.spinner.View()))
		return v
	}

	if !m.ready {
		return v
	}

	var b strings.Builder
	b.WriteString(m.renderHeader())
	b.WriteString(m.viewport.View())
	b.WriteString("\n")
	b.WriteString(m.renderFooter())
	v.SetContent(b.String())
	return v
}

func (m activityModel) renderHeader() string {
	if m.stats == nil {
		return ""
	}
	var buf bytes.Buffer
	buf.WriteString("\n")
	renderStatCards(&buf, m.sty, *m.stats)
	buf.WriteString("\n")
	renderContributionChart(&buf, m.sty, m.hourly, m.repos)
	buf.WriteString("\n")
	renderRepoChart(&buf, m.sty, m.repos)
	buf.WriteString("\n")
	return buf.String()
}

func (m activityModel) headerLineCount() int {
	return strings.Count(m.renderHeader(), "\n")
}

func (m activityModel) renderCommits() string {
	var buf bytes.Buffer
	renderCommitListN(&buf, m.sty, m.days, -1)
	return buf.String()
}

func (m activityModel) renderFooter() string {
	if !m.sty.colorEnabled {
